<template>
  <div class="card back-white" :class="{ disabled: !isEnabled }">
    <div class="card-title">{{ $t('execution_order') }}</div>

    <div class="hint-banner compact">
      <q-icon name="info_outline" size="14px" />
      <span>{{ isEnabled ? $t('execution_order_hint') : $t('select_doc_type_first') }}</span>
    </div>

    <div class="order-list" v-if="isEnabled">
      <!-- Run First (always visible when enabled) -->
      <button
        type="button"
        @click="setExecutionOrder('first')"
        :class="['order-item', { active: executionOrder === 'first' }]"
      >
        <div class="order-icon">
          <q-icon name="arrow_upward" size="12px" />
        </div>
        <div class="order-content">
          <span class="order-label text-dark-mode">{{ $t('run_first') }}</span>
          <span class="order-hint">{{ $t('before_all') }}</span>
        </div>
        <q-icon v-if="executionOrder === 'first'" name="check" size="16px" class="order-check" />
      </button>

      <!-- Existing exports (only shown if list has items) -->
      <template v-if="existingExports.length > 0">
        <button
          v-for="(exp, index) in existingExports"
          :key="exp.id"
          type="button"
          @click="setExecutionOrder(`after-${index}`)"
          :class="['order-item', { active: executionOrder === `after-${index}` }]"
        >
          <div class="order-number">{{ index + 1 }}</div>
          <div class="order-content">
            <span class="order-label text-dark-mode">{{ $t('run_after') }}</span>
            <span class="order-hint">{{ exp.title }} ({{ exp.exportMethod }})</span>
          </div>
          <q-icon v-if="executionOrder === `after-${index}`" name="check" size="16px" class="order-check" />
        </button>

        <!-- Run Last (only shown if list has items) -->
        <button
          type="button"
          @click="setExecutionOrder('last')"
          :class="['order-item', { active: executionOrder === 'last' }]"
        >
          <div class="order-icon">
            <q-icon name="arrow_downward" size="12px" />
          </div>
          <div class="order-content">
            <span class="order-label text-dark-mode">{{ $t('run_last') }}</span>
            <span class="order-hint">{{ $t('after_all') }} (#{{ existingExports.length + 2 }})</span>
          </div>
          <q-icon v-if="executionOrder === 'last'" name="check" size="16px" class="order-check" />
        </button>
      </template>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocExportStore } from 'src/store/main';

export default defineComponent({
  name: 'ExecutionOrderCard',
  data() {
    const doc_export_store = useDocExportStore();

    return {
      doc_export_store,
      executionOrder: '' as string,
      existingExports: [] as Array<{ id: number; title: string; exportMethod: string; executionOrder: number }>,
    };
  },
  computed: {
    configuration(): any {
      return this.doc_export_store.selected_configuration;
    },
    configurations(): any[] {
      return this.doc_export_store.configurations || [];
    },
    isEnabled(): boolean {
      return !!this.configuration?.doc_type;
    },
  },
  watch: {
    'configuration.sub_org_id'() {
      this.loadExistingExports();
    },
    'configuration.doc_type'() {
      this.loadExistingExports();
    },
  },
  async created() {
    // Only fetch configurations if not already loaded in the store
    if (this.configurations.length === 0) {
      await this.doc_export_store.getExportConfigurations();
    }
    this.loadExistingExports();
  },
  methods: {
    setExecutionOrder(order: string) {
      this.executionOrder = order;

      if (order === 'first') {
        this.configuration.execution_order = 1;
      } else if (order === 'last') {
        this.configuration.execution_order = this.existingExports.length + 2;
      } else if (order.startsWith('after-')) {
        // after-0 → execution_order = 2, after-1 → execution_order = 3
        const index = parseInt(order.split('-')[1]);
        this.configuration.execution_order = index + 2;
      }
    },

    loadExistingExports() {
      const { sub_org_id, doc_type, id: currentId, execution_order: currentOrder } = this.configuration || {};

      // Only doc_type is required; sub_org_id is optional
      if (!doc_type) {
        this.existingExports = [];
        this.executionOrder = '';
        if (this.configuration) {
          this.configuration.execution_order = null;
        }
        return;
      }

      // Filter and map configurations, sorted by execution_order
      // sub_org_id match: both must be equal (including both being null/empty)
      this.existingExports = this.configurations
        .filter((c: any) => c.id !== currentId && c.is_active === true && (c.sub_org_id || null) === (sub_org_id || null) && c.doc_type === doc_type)
        .map((c: any) => ({
          id: c.id,
          title: c.title || c.name || 'Untitled',
          exportMethod: c.export_method || 'Watcher',
          executionOrder: c.execution_order || 0,
        }))
        .sort((a, b) => a.executionOrder - b.executionOrder);

      // Determine selection
      this.selectDefaultOrder(currentId, currentOrder);
    },

    selectDefaultOrder(currentId: number | undefined, currentOrder: number | undefined) {
      const count = this.existingExports.length;

      // No existing exports - only "Run First" available
      if (count === 0) {
        this.executionOrder = 'first';
        this.configuration.execution_order = 1;
        return;
      }

      // Edit mode with existing order
      const isEditMode = currentId && currentOrder;
      if (isEditMode) {
        if (currentOrder === 1) {
          this.executionOrder = 'first';
        } else if (currentOrder > count + 1) {
          this.executionOrder = 'last';
        } else {
          // Position N means select "after-(N-2)" since after-0 = position 2
          const afterIndex = currentOrder - 2;
          if (afterIndex >= 0 && afterIndex < count) {
            this.executionOrder = `after-${afterIndex}`;
          } else {
            this.executionOrder = 'last';
          }
        }
        return;
      }

      // New mode - default to "Run Last"
      this.executionOrder = 'last';
      this.configuration.execution_order = count + 2;
    },
  },
});
</script>

