<template>
  <div class="deployment-field">
    <label class="export-field-label">Deployment Type <span class="export-required">*</span></label>
    <div class="deployment-options">
      <button
        type="button"
        :class="['deploy-option', { active: configuration.cloud === true }]"
        :disabled="configuration.id && configuration.id !== 0"
        @click="setDeploymentType(true)"
      >
        <div class="option-header">
          <span class="option-title text-dark-mode">CLOUD</span>
          <q-icon v-if="configuration.cloud === true" name="check" size="16px" class="check-icon" />
        </div>
        <span class="option-desc">Cloud-based ION</span>
      </button>
      <button
        type="button"
        :class="['deploy-option', { active: configuration.cloud === false }]"
        :disabled="configuration.id && configuration.id !== 0"
        @click="setDeploymentType(false)"
      >
        <div class="option-header">
          <span class="option-title text-dark-mode">ON-PREMISE</span>
          <q-icon v-if="configuration.cloud === false" name="check" size="16px" class="check-icon" />
        </div>
        <span class="option-desc">On-premise ION</span>
      </button>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { useDocExportStore } from 'src/store/main';

export default defineComponent({
  name: 'DeploymentTypeField',
  setup() {
    const doc_export_store = useDocExportStore();
    const { selected_configuration, selected_export, export_types } = storeToRefs(doc_export_store);

    return {
      configuration: selected_configuration,
      selected_export,
      export_types,
    };
  },
  methods: {
    setDeploymentType(isCloud: boolean) {
      this.configuration.cloud = isCloud;

      // Update export method based on deployment type for IDM
      if (this.selected_export === this.export_types.INFOR_IDM_CLOUD ||
          this.selected_export === this.export_types.INFOR_IDM_ON_PREMISE) {
        this.configuration.export_method = isCloud
          ? this.export_types.INFOR_IDM_CLOUD
          : this.export_types.INFOR_IDM_ON_PREMISE;
      }

      // Update export method based on deployment type for ION
      if (this.selected_export === this.export_types.INFOR_ION_CLOUD ||
          this.selected_export === this.export_types.INFOR_ION_ON_PREMISE) {
        this.configuration.export_method = isCloud
          ? this.export_types.INFOR_ION_CLOUD
          : this.export_types.INFOR_ION_ON_PREMISE;
      }

      // Update export method based on deployment type for BOD
      if (this.selected_export === this.export_types.INFOR_BOD_CLOUD ||
          this.selected_export === this.export_types.INFOR_BOD_ON_PREMISE) {
        this.configuration.export_method = isCloud
          ? this.export_types.INFOR_BOD_CLOUD
          : this.export_types.INFOR_BOD_ON_PREMISE;
      }

      // Generic API uses a single export_method — cloud/on-premise is determined by the on_premise flag on save
    },
  },
});
</script>

