<template>
  <q-select
    outlined
    dense
    clearable
    v-model="selected_configuration['sub_org_id']"
    use-input
    :options="filteredOptions"
    @filter="filterSubOrgslistEvent"
    :label="$t('sub_organizations')"
    :loading="sub_org_list_loading"
    emit-value
    map-options
    popup-content-class="dropdown-fit"
  >
    <template v-slot:option="scope">
      <q-item v-bind="scope.itemProps">
        <q-item-section>
          <q-item-label>{{ scope.opt.label }}</q-item-label>
          <q-tooltip>{{ scope.opt.label }}</q-tooltip>
        </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>

<script lang="ts">
import { defineComponent, ref, computed, watch } from 'vue';
import { storeToRefs } from 'pinia';
import { useDropdownStore, useDocExportStore } from 'src/store/main';

export default defineComponent({
  name: 'SubOrgSelect',
  setup() {
    const dropdown_store = useDropdownStore();
    const { subOrgList, sub_org_list_loading } = storeToRefs(dropdown_store);
    const doc_export_store = useDocExportStore();
    const { selected_configuration } = storeToRefs(doc_export_store);

    // Track the current filter text
    const filterText = ref('');

    // Computed property that reactively filters options based on subOrgList and filterText
    const filteredOptions = computed(() => {
      if (!filterText.value) {
        return subOrgList.value;
      }
      const needle = filterText.value.toLowerCase();
      return subOrgList.value.filter(
        (v: any) => v.label?.toLowerCase().indexOf(needle) > -1,
      );
    });

    // Filter event handler for q-select
    const filterSubOrgslistEvent = (val: string, update: any, abort: any) => {
      update(() => {
        filterText.value = val || '';
      });
    };

    return {
      selected_configuration,
      subOrgList,
      sub_org_list_loading,
      filteredOptions,
      filterSubOrgslistEvent,
    };
  },
});
</script>
