<template>
  <div class="watcher-fields">
    <!-- Export Folder -->
    <div class="export-form-group">
      <label class="export-form-label">
        {{ $t('export_folder') }} <span class="export-required">*</span>
      </label>
      <q-input
        data-cy="export-folder"
        outlined
        dense
        hide-bottom-space
        v-model="configuration.export_folder"
        placeholder="C:\Export or \\server\share"
        :rules="[(val: any) => val && val.length > 0]"
      />
      <div class="text-caption text-grey-6 q-mt-xs">
        {{ $t('export_folder_hint') }}
      </div>
    </div>

    <!-- XSLT Template Selection -->
    <div class="export-form-row">
      <div class="export-form-group">
        <label class="export-form-label">{{ $t('xslt_template') }}</label>
        <q-select
          v-model="configuration.xslt_template_id"
          outlined
          dense
          clearable
          :options="xsltTemplates"
          option-value="id"
          option-label="name"
          emit-value
          map-options
          :placeholder="$t('select_template')"
          :loading="loadingTemplates"
        >
          <template v-slot:no-option>
            <q-item>
              <q-item-section class="text-grey">
                {{ $t('no_templates_available') }}
              </q-item-section>
            </q-item>
          </template>
        </q-select>
        <div class="text-caption text-grey-6 q-mt-xs">
          {{ $t('xslt_template_default_hint') }}
        </div>
      </div>

      <div class="export-form-group">
        <label class="export-form-label">{{ $t('upload_new_xslt') }}</label>
        <f-file
          v-model="newTemplateFile"
          accept=".xslt,.xsl"
          :action-text="$t('click_to_upload')"
          :drag-text="$t('drag_and_drop')"
          :hint="$t('file_hint_xslt')"
          size="sm"
        />
      </div>
    </div>

    <!-- Enabled Toggle -->
    <div class="export-toggle-container">
      <div class="export-toggle-row">
        <div class="export-toggle-info">
          <q-icon name="power_settings_new" class="export-toggle-icon" color="primary" />
          <div class="export-toggle-text">
            <div class="title">{{ $t('enabled') }}</div>
            <div class="description">{{ $t('watcher_enabled_description') }}</div>
          </div>
        </div>
        <f-toggle
          v-model="configuration.enabled"
          size="md"
        />
      </div>
    </div>

    <!-- PDF Export Toggle -->
    <div class="export-toggle-container">
      <div class="export-toggle-row">
        <div class="export-toggle-info">
          <q-icon name="picture_as_pdf" class="export-toggle-icon" color="primary" />
          <div class="export-toggle-text">
            <div class="title">{{ $t('export_pdf') }}</div>
            <div class="description">{{ $t('export_pdf_description') }}</div>
          </div>
        </div>
        <f-toggle
          v-model="configuration.export_pdf_enabled"
          size="md"
        />
      </div>
    </div>

    <!-- PDF Export Folder (conditional) -->
    <div v-if="configuration.export_pdf_enabled" class="export-form-group pdf-folder-group">
      <label class="export-form-label">
        {{ $t('pdf_export_folder') }}
        <span class="text-grey-6">({{ $t('optional') }})</span>
      </label>
      <q-input
        outlined
        dense
        hide-bottom-space
        v-model="configuration.pdf_export_folder"
        :placeholder="$t('pdf_export_folder_placeholder')"
      />
      <div class="text-caption text-grey-6 q-mt-xs">
        {{ $t('pdf_export_folder_hint') }}
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useDocExportStore } from 'src/store/main';
import { exportApiService } from 'src/services';

export default defineComponent({
  name: 'WatcherFields',
  setup() {
    const doc_export_store = useDocExportStore();
    const { selected_configuration } = storeToRefs(doc_export_store);

    return {
      configuration: selected_configuration,
      xsltTemplates: ref([] as any[]),
      loadingTemplates: ref(false),
      newTemplateFile: ref(null as File | null),
    };
  },
  mounted() {
    this.loadTemplates();
  },
  methods: {
    async loadTemplates() {
      try {
        this.loadingTemplates = true;
        const response = await exportApiService.getWatchdogTemplates();
        // API returns { success, templates, message }
        if (response && response.templates) {
          this.xsltTemplates = response.templates;
        }
      } catch (err: any) {
        logError(err);
      } finally {
        this.loadingTemplates = false;
      }
    },
    // Expose method to upload template before saving
    async uploadTemplateIfNeeded(): Promise<string | null> {
      if (!this.newTemplateFile) {
        return null;
      }

      try {
        const response = await exportApiService.createWatchdogTemplate(
          this.newTemplateFile,
        );
        const templateId = response?.template?.id || response?.data?.id;
        if (templateId) {
          await this.loadTemplates();
          return templateId;
        }
      } catch (err: any) {
        logError(err);
      }
      return null;
    },
  },
});
</script>

