<template>

<!-- AS discussed to create the BOD on the UI side will be enabled later on as soon as the things are smooth -->
  <div class="export-file-field" v-if="true">
    <label class="export-field-label">{{ $t('bod_mapping_label') }}</label>
    <f-file
      v-model="configuration.bod_file"
      accept=".properties"
      :action-text="$t('click_to_upload')"
      :drag-text="$t('drag_and_drop')"
      :hint="$t('file_hint_properties')"
      size="sm"
    />
    <f-btn
      v-if="configuration && configuration.infor_bod_mapping"
      appearance="tertiary"
      :label="$t('download')"
      size="sm"
      class="export-download-btn"
      @click="downloadMappingFile('BOD_MAPPING', 'BOD-Mapping.properties', configuration.id)"
    />
  </div>
  <div class="bod-mapping-field" v-else>
    <label class="export-field-label">{{ $t('bod_mapping_label') }}</label>

    <!-- Upload Area -->
    <f-file
      v-model="uploadedFile"
      accept=".properties"
      :action-text="$t('click_to_upload')"
      :drag-text="$t('drag_and_drop') + ' to replace/merge'"
      :hint="$t('file_hint_properties')"
      size="sm"
      @update:model-value="handleFileUpload"
    />

    <div class="bod-actions">
      <!-- DO not show this option right now will be improved later -->
      <f-btn
      v-if="false"
        label="Add Entry"
        icon="add"
        size="sm"
        appearance="secondary"
        @click="addEntry"
      />
      <f-btn
        v-if="configuration && configuration.infor_bod_mapping"
        appearance="tertiary"
        :label="$t('download')"
        icon="download"
        size="sm"
        @click="downloadMappingFile('BOD_MAPPING', 'BOD-Mapping.properties', configuration.id)"
      />
    </div>

    <!-- Mapping Editor Table -->
    <div class="mapping-table-container shadow-1 rounded-borders overflow-hidden">
      <DocBitsTable
        :rows="mappingEntries"
        :columns="columns"
        row-key="id"
        tableId="bod-mapping-table"
        :loading="loading"
        dense
        :features="{
          sorting: true,
          filtering: true,
          pagination: true,
          clientSideSort: true,
          clientSideFilter: true,
          clientSidePagination: true
        }"
        :pagination="{ rowsPerPage: 10 }"
      >
        <!-- Key Column -->
        <template v-slot:body-cell-key="{ row }">
          <q-input
            v-model="row.key"
            dense
            borderless
            class="editable-cell-input"
            placeholder="Enter key"
            @blur="updateConfigurationFile"
          />
        </template>

        <!-- Value Column -->
        <template v-slot:body-cell-value="{ row }">
          <q-input
            v-model="row.value"
            dense
            borderless
            class="editable-cell-input"
            placeholder="Enter value"
            @blur="updateConfigurationFile"
          />
        </template>

        <!-- Actions Column -->
        <template v-slot:body-cell-__actions__="{ row, rowIndex }">
          <div class="row justify-end">
            <q-btn
              flat
              dense
              round
              icon="delete"
              color="negative"
              size="sm"
              @click="removeEntry(rowIndex)"
            >
              <q-tooltip>Remove Entry</q-tooltip>
            </q-btn>
          </div>
        </template>

        <template v-slot:bottom-row>
           <q-tr v-if="mappingEntries.length === 0 && !loading">
             <q-td colspan="100%" class="text-center text-grey-6 q-pa-md">
               No mapping entries yet. Upload a file or add entries manually.
             </q-td>
           </q-tr>
        </template>
      </DocBitsTable>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, onMounted, watch } from 'vue';
import { storeToRefs } from 'pinia';
import { useDocExportStore } from 'src/store/main';
import exportUtil from 'src/utils/export';
import { DocBitsTable } from 'src/components/Table';
import { exportApiService } from 'src/services';
import { uid } from 'quasar';

export interface MappingEntry {
  id: string;
  key: string;
  value: string;
}

export default defineComponent({
  name: 'BodMappingFileField',
  mixins: [exportUtil],
  components: {
    DocBitsTable,
  },
  setup() {
    const doc_export_store = useDocExportStore();
    const { selected_configuration } = storeToRefs(doc_export_store);
    const configuration = selected_configuration;

    const loading = ref(false);
    const mappingEntries = ref<MappingEntry[]>([]);
    const uploadedFile = ref<File | null>(null);

    const columns = [
      {
        name: 'key',
        label: 'Key / Source',
        field: 'key',
        align: 'left' as const,
        sortable: true,
        style: 'min-width: 200px',
      },
      {
        name: 'value',
        label: 'Value / Target',
        field: 'value',
        align: 'left' as const,
        sortable: true,
        style: 'min-width: 200px',
      },
      {
        name: '__actions__',
        label: '',
        field: '__actions__',
        align: 'right' as const,
        style: 'width: 50px',
      },
    ];

    const parsePropertiesContent = (content: string) => {
      const entries: MappingEntry[] = [];
      const lines = content.split(/\r?\n/);
      
      lines.forEach(line => {
        const trimmed = line.trim();
        // Skip comments and empty lines
        if (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('!')) {
          return;
        }

        // Split by first = or :
        // This regex finds the first occurrence of = or : 
        // Handles cases like "key=value" or "key:value" or "key = value"
        const separatorIndex = line.indexOf('='); 
        const colonIndex = line.indexOf(':');
        
        let splitIndex = -1;
        if (separatorIndex !== -1 && colonIndex !== -1) {
            splitIndex = Math.min(separatorIndex, colonIndex);
        } else {
            splitIndex = Math.max(separatorIndex, colonIndex);
        }

        if (splitIndex !== -1) {
          const key = line.substring(0, splitIndex).trim();
          const value = line.substring(splitIndex + 1).trim();
          entries.push({
            id: uid(),
            key,
            value
          });
        }
      });
      
      return entries;
    };

    const fetchExistingMapping = async () => {
      if (configuration.value && configuration.value.infor_bod_mapping && configuration.value.id) {
        loading.value = true;
        try {
          // Re-using the getMappingFile service which returns a Blob
          const response = await exportApiService.getMappingFile(configuration.value.id, 'BOD_MAPPING');
          
          if (response instanceof Blob) {
            const text = await response.text();
            mappingEntries.value = parsePropertiesContent(text);
          }
        } catch (error) {
          console.error('Failed to fetch BOD mapping:', error);
        } finally {
          loading.value = false;
        }
      }
    };

    const handleFileUpload = async (file: File | null) => {
      if (!file) return;

      // Assign the original file directly to preserve comments and formatting
      configuration.value.bod_file = file;

      loading.value = true;
      try {
        const text = await file.text();
        mappingEntries.value = parsePropertiesContent(text);
      } catch (error) {
        console.error('Error parsing uploaded file:', error);
      } finally {
        loading.value = false;
      }
    };

    const generatePropertiesContent = (): string => {
      return mappingEntries.value
        .filter(entry => entry.key && entry.key.trim())
        .map(entry => `${entry.key}=${entry.value}`)
        .join('\n');
    };

    const updateConfigurationFile = () => {
      const content = generatePropertiesContent();
      const file = new File([content], 'BOD-Mapping.properties', { type: 'text/x-java-properties' });
      configuration.value.bod_file = file;
    };

    const addEntry = () => {
      mappingEntries.value.unshift({
        id: uid(),
        key: '',
        value: ''
      });
    };

    const removeEntry = (index: number) => {
      mappingEntries.value.splice(index, 1);
      updateConfigurationFile();
    };

    // AS discussed to create the BOD on the UI side will be enabled later on as soon as the things are smooth
    // onMounted(() => {
    //   fetchExistingMapping();
    // });

    return {
      configuration,
      mappingEntries,
      columns,
      loading,
      uploadedFile,
      handleFileUpload,
      addEntry,
      removeEntry,
      updateConfigurationFile,
    };
  },
});
</script>

