<template>
  <div class="toml-mapping-field">
    <div class="export-form-group no-margin">
      <label class="export-form-label">{{ $t('toml_mapping_label') }}</label>
      <!-- Sample selected: match f-file selected state -->
      <div v-if="sampleMappingName" class="sample-selected">
        <div class="sample-selected__icon">
          <q-icon name="description" size="24px" />
        </div>
        <div class="sample-selected__info">
          <span class="sample-selected__name">{{ sampleMappingName }}</span>
          <span class="sample-selected__hint">{{ $t('select_toml_sample') }}</span>
        </div>
        <q-btn flat round dense icon="close" size="sm" class="sample-selected__clear" @click="clearSample" />
      </div>
      <!-- No sample: show normal file uploader -->
      <f-file
        v-else
        v-model="configuration.toml_file"
        accept=".toml"
        :action-text="$t('click_to_upload')"
        :drag-text="$t('drag_and_drop')"
        :hint="$t('file_hint_toml')"
        size="sm"
        @update:model-value="onTomlUpdate()"
      />
      <div class="toml-actions">
        <f-btn
          v-if="hasExistingMapping && !isGLS840MI"
          appearance="tertiary"
          :label="$t('edit')"
          size="sm"
          @click="editTomlFile(configuration.infor_m3_toml_mapping_id)"
        />
        <f-btn
          v-if="!isGLS840MI"
          appearance="tertiary"
          :label="$t('select_toml_sample')"
          size="sm"
          @click="openSampleDlg()"
        />
        <f-btn
          v-if="hasExistingMapping"
          appearance="tertiary"
          :label="$t('download')"
          size="sm"
          @click="downloadMappingFile(isVertex ? 'VERTEX_MAPPING' : isGLS840MI ? 'API_EXPORT_MAPPING' : 'M3_TOML_MAPPING', isVertex ? 'Vertex-Mapping.toml' : isGLS840MI ? 'API-Export-Mapping.toml' : 'M3-TOML-Mapping.toml', configuration.id)"
        />
      </div>
    </div>

    <!-- TOML Samples Dialog -->
    <q-dialog
      v-model="showTomlSamples"
      persistent
      @keydown.esc="showTomlSamples = false"
    >
      <q-card class="toml-dialog">
        <q-card-section class="row items-center q-pb-sm bg-primary">
          <div class="text-h6 text-white">
            <b>{{ $t('select_toml_sample') }}</b>
          </div>
          <q-space />
          <q-btn
            color="white"
            icon="close"
            flat
            round
            dense
            @click="showTomlSamples = false"
          />
        </q-card-section>

        <q-linear-progress
          v-if="loadingSamples"
          indeterminate
          color="primary"
        />

        <q-card-section>
          <div v-if="loadingSamples" class="toml-samples-empty">
            {{ $t('loading') }}...
          </div>
          <div v-else-if="tomlSamples.length === 0" class="toml-samples-empty">
            <q-icon name="sym_o_info" size="32px" color="grey-6" />
            <div>{{ $t('no_samples_available') }}</div>
          </div>
          <div v-else class="toml-samples-grid">
            <template v-for="sample of tomlSamples" :key="sample.id">
              <q-card
                class="toml-sample-card"
                flat
                bordered
                @click="selectSample(sample.id, sample.mapping_name)"
              >
                <div class="toml-sample-icon">
                  <Icon icon="mdi:code-json" width="60" height="60" />
                </div>
                <div class="toml-sample-name">
                  {{ sample.mapping_name }}
                </div>
              </q-card>
            </template>
          </div>
        </q-card-section>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { useDocExportStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { exportApiService } from 'src/services';
import exportUtil from 'src/utils/export';
import { M3_TOML_MAPPING } from 'src/constants';
export default defineComponent({
  name: 'TomlMappingFileField',
  
  mixins: [exportUtil],
  setup() {
    const doc_export_store = useDocExportStore();
    const { selected_configuration, processing, selected_export } = storeToRefs(doc_export_store);
    return {
      configuration: selected_configuration,
      processing,
      selected_export,
      export_types: doc_export_store.export_types,
    };
  },
  data() {
    return {
      sampleMappingName: '',
      showTomlSamples: false,
      loadingSamples: false,
      tomlSamples: [] as any,
    };
  },
  computed: {
    isGLS840MI(): boolean {
      return this.selected_export === this.export_types.INFOR_GLS840MI ||
        this.selected_export === this.export_types.INFOR_M3_OC_CHARGES_ONPREMISE ||
        this.selected_export === this.export_types.INFOR_M3_PACKING_UNIT_ONPREMISE ||
        this.selected_export === this.export_types.VERTEX ||
        this.selected_export === this.export_types.GENERIC_API;
    },
    isVertex(): boolean {
      return this.selected_export === this.export_types.VERTEX;
    },
    hasExistingMapping(): boolean {
      if (this.isVertex) {
        return !!this.configuration?.vertex_mapping_id;
      }
      return this.isGLS840MI
        ? !!this.configuration?.api_export_mapping_id
        : !!this.configuration?.infor_m3_toml_mapping;
    },
  },
  methods: {
    editTomlFile(inforM3TomlMappingId: string) {
      this.$router.push('/settings/rule-management/' + inforM3TomlMappingId);
    },
    onTomlUpdate() {
      this.sampleMappingName = '';
      this.configuration.m3_toml_mapping_id = null;
    },
    async openSampleDlg() {
      this.showTomlSamples = true;

      if (this.tomlSamples.length > 0) {
        return;
      }

      await this.loadTomlSamples();
    },
    async loadTomlSamples() {
      try {
        this.loadingSamples = true;

        const response =
          await exportApiService.getExportConfigurationMappingSamples(
            M3_TOML_MAPPING,
          );

        if (response && !response.success && response.exception.detail) {
          throw { message: response.exception.detail };
        }

        this.tomlSamples = response.data;
      } catch (err: any) {
        logError(err);
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      } finally {
        this.loadingSamples = false;
      }
    },
    clearSample() {
      this.sampleMappingName = '';
      this.configuration.m3_toml_mapping_id = null;
    },
    selectSample(sampleId: string, sampleMappingName: string) {
      this.showTomlSamples = false;
      this.configuration.toml_file = null;
      this.configuration.infor_m3_toml_mapping = null;
      this.configuration.m3_toml_mapping_id = sampleId;
      this.sampleMappingName = sampleMappingName;
    },
  },
});
</script>

