import { exportApiService } from 'src/services';
export default {
  methods: {
    async downloadMappingFile(
      config_type: string,
      fileName: string,
      id: number,
    ) {
      try {
        const response = await exportApiService.getMappingFile(id, config_type);

        if (response.error) {
          throw response.error;
        }

        const fileURL = window.URL.createObjectURL(new Blob([response]));
        const fileLink = document.createElement('a');
        fileLink.href = fileURL;
        fileLink.setAttribute('download', fileName);
        document.body.appendChild(fileLink);
        fileLink.click();
        fileLink.remove();
      } catch (err: any) {
        logError(err);
      } finally {
      }
    },
  },
};
