<template>
  <div class="sftp-smb-fields">
    <!-- Server URL and Port Row -->
    <div class="export-form-row">
      <div class="export-form-group">
        <label class="export-form-label">
          {{ $t('server_url') }} <span class="export-required">*</span>
        </label>
        <q-input
          data-cy="server-url"
          outlined
          dense
          hide-bottom-space
          v-model="configuration.export_url"
          :placeholder="isSFTP ? 'sftp.example.com' : '//server/share'"
          :rules="[(val: any) => val && val.length > 0]"
        />
      </div>

      <div class="export-form-group">
        <label class="export-form-label">
          {{ $t('port') }} <span class="export-required">*</span>
        </label>
        <q-input
          data-cy="port"
          outlined
          dense
          hide-bottom-space
          v-model="configuration.export_port"
          :placeholder="isSFTP ? '22' : '445'"
          :rules="[(val: any) => val && val.length > 0]"
        />
      </div>
    </div>

    <!-- Folder -->
    <div class="export-form-group">
      <label class="export-form-label">
        {{ $t('export_folder_path') }} <span class="export-required">*</span>
      </label>
      <q-input
        data-cy="folder"
        outlined
        dense
        hide-bottom-space
        v-model="configuration.export_folder"
        placeholder="/exports/documents"
        :rules="[(val: any) => val && val.length > 0]"
      />
    </div>

    <!-- Username and Password Row -->
    <div class="export-form-row">
      <div class="export-form-group">
        <label class="export-form-label">
          {{ $t('username') }} <span class="export-required">*</span>
        </label>
        <q-input
          data-cy="username"
          outlined
          dense
          hide-bottom-space
          v-model="configuration.username"
          placeholder="username"
          :rules="[(val: any) => val && val.length > 0]"
        />
      </div>

      <div class="export-form-group">
        <label class="export-form-label">
          {{ $t('password') }} <span class="export-required">*</span>
        </label>
        <q-input
          data-cy="password"
          outlined
          dense
          hide-bottom-space
          v-model="configuration.password"
          type="password"
          placeholder="••••••••"
          :rules="[(val: any) => val && val.length > 0]"
        />
      </div>
    </div>

    <!-- XSLT File - Only for SFTP -->
    <div class="export-form-group" v-if="isSFTP">
      <label class="export-form-label">{{ $t('xslt_mapping_label') }}</label>
      <f-file
        v-model="configuration.export_xslt_file"
        accept=".xslt,.xsl"
        :action-text="$t('click_to_upload')"
        :drag-text="$t('drag_and_drop')"
        :hint="$t('file_hint_xslt')"
        size="sm"
      />
      <f-btn
        v-if="configuration && configuration.export_xslt"
        appearance="tertiary"
        :label="$t('download')"
        size="sm"
        class="export-download-btn"
        @click="downloadMappingFile('XSLT_MAPPING', 'export.xslt', configuration.id)"
      />
    </div>

    <!-- JPL Mapping File - Only for SMB -->
    <div class="export-form-group" v-if="isSMB">
      <label class="export-form-label">{{ $t('jpl_mapping_label') }}</label>
      <f-file
        v-model="configuration.jpl_mapping_file"
        :action-text="$t('click_to_upload')"
        :drag-text="$t('drag_and_drop')"
        :hint="$t('file_hint_jpl')"
        size="sm"
      />
      <f-btn
        v-if="configuration && configuration.jpl_mapping"
        appearance="tertiary"
        :label="$t('download')"
        size="sm"
        class="export-download-btn"
        @click="downloadMappingFile('JPL_MAPPING', 'jpl-mapping.xml', configuration.id)"
      />
    </div>

    <!-- Advanced Settings - Only for SFTP (Collapsible) -->
    <div class="export-advanced-section" v-if="isSFTP">
      <div class="export-advanced-header" @click="advancedExpanded = !advancedExpanded">
        <div class="export-advanced-title">
          <q-icon
            name="chevron_right"
            :class="{ 'export-chevron-rotated': advancedExpanded }"
            class="export-chevron-icon"
          />
          <span>{{ $t('advanced_settings') }}</span>
        </div>
        <span class="export-advanced-hint">
          {{ advancedExpanded ? $t('click_to_collapse') : $t('click_to_expand') }}
        </span>
      </div>

      <q-slide-transition>
        <div v-show="advancedExpanded" class="export-advanced-content">
          <!-- Filename Export Mode -->
          <div class="export-toggle-container">
            <div class="export-toggle-row">
              <div class="export-toggle-info">
                <q-icon name="description" class="export-toggle-icon" color="primary" />
                <div class="export-toggle-text">
                  <div class="title">{{ $t('filename_export_mode') }}</div>
                  <div class="description">
                    <template v-if="configuration.filename_export_mode">
                      {{ $t('use_docbits_id_format') }}: <code>12345.pdf/xml</code>
                    </template>
                    <template v-else>
                      {{ $t('keep_original_filename') }}: <code>invoice.pdf</code>
                    </template>
                  </div>
                </div>
              </div>
              <f-toggle
                v-model="configuration.filename_export_mode"
                size="md"
              />
            </div>
            <div class="export-toggle-labels">
              <span class="label" :class="{ 'selected': !configuration.filename_export_mode }">
                {{ $t('original') }}
              </span>
              <span class="label" :class="{ 'selected': configuration.filename_export_mode }">
                {{ $t('docbits_id') }}
              </span>
            </div>
          </div>

          <!-- Include Document History -->
          <div class="export-toggle-container">
            <div class="export-toggle-row">
              <div class="export-toggle-info">
                <q-icon name="folder_open" class="export-toggle-icon" color="primary" />
                <div class="export-toggle-text">
                  <div class="title">{{ $t('include_document_history') }}</div>
                  <div class="description">{{ $t('include_document_history_description') }}</div>
                </div>
              </div>
              <f-toggle
                v-model="configuration.export_document_history"
                size="md"
              />
            </div>
          </div>
        </div>
      </q-slide-transition>
    </div>

    <!-- Test Connection Button - For both SFTP and SMB -->
    <div class="test-connection">
      <f-btn
        appearance="tertiary"
        :label="$t('test_connection')"
        icon="wifi_tethering"
        :loading="testing"
        @click="testConnection"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { useDocExportStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { exportApiService } from 'src/services';
import exportUtil from 'src/utils/export';
export default defineComponent({
  name: 'SFTPSMBFields',
  mixins: [exportUtil],
  setup() {
    const doc_export_store = useDocExportStore();
    const { selected_configuration, selected_export, export_types } = storeToRefs(doc_export_store);
    return {
      configuration: selected_configuration,
      selected_export,
      export_types,
    };
  },
  data() {
    return {
      testing: false,
      advancedExpanded: false,
    };
  },
  computed: {
    isSFTP(): boolean {
      return this.selected_export === this.export_types.SFTP;
    },
    isSMB(): boolean {
      return this.selected_export === this.export_types.SMB_WITH_JPL;
    },
  },
  methods: {
    async testConnection() {
      try {
        // Test connection requires a saved configuration
        if (!this.configuration.id || this.configuration.id === 0) {
          notify.warning(this.$t('save_before_test'));
          return;
        }

        this.testing = true;
        const data = {
          config_id: this.configuration.id,
        };

        // Call appropriate API based on export type
        let response;
        if (this.isSFTP) {
          response = await exportApiService.testSFTP(data);
        } else if (this.isSMB) {
          response = await exportApiService.testSMB(data);
        }

        if (response && response.success !== false) {
          notify.success(this.$t('test_connection_success'));
        } else {
          throw { message: response?.message };
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        const detail_info = err.extra_data ? ' ' + err.extra_data : '';
        notify.error(msg + detail_info);
      } finally {
        this.testing = false;
      }
    },
  },
});
</script>

<style scoped lang="scss">
.test-connection {
  margin-top: 10px;
}
</style>
