<template>
  <div class="page-container">
    <div class="settings-page-content export-config-page">
    <!-- Header -->
    <div class="page-header" v-if="false">
      <div class="header-left">
        <h1 class="page-title">{{ configuration.id === 0 ? $t('add_export_configuration') : $t('edit_export_configuration') }}</h1>
        <p class="page-subtitle">{{ $t('configure_export_destination') }}{{ selected_export ? ` for ${getExportTypeLabel}` : '' }}</p>
      </div>
      <q-btn icon="close" flat round dense color="grey-7" @click="goBack" />
    </div>

    <!-- Main Content -->
    <div :class="['content-grid', { 'content-grid--single': !isMultipleExportEnabled }]">
      <!-- Left Column -->
      <div class="main-column scrollable-column">
        <!-- Basic Information -->
        <div class="card back-white">
          <div class="card-title">{{ $t('basic_information') }}</div>

          <div class="export-form-group">
            <label class="export-field-label">{{ $t('configuration_title') }} <span class="export-required">*</span></label>
            <q-input
              data-cy="title"
              outlined
              dense
              hide-bottom-space
              v-model="configurationTitle"
              placeholder="e.g., My Export Configuration"
              :rules="[(val: any) => val && val.length > 0]"
            />
          </div>

          <div class="export-form-row">
            <div class="export-form-group">
              <label class="export-field-label">{{ $t('sub_organization') }}</label>
              <SubOrgSelect />
            </div>
            <div class="export-form-group">
              <label class="export-field-label">{{ $t('document_type') }} <span class="export-required">*</span></label>
              <q-select
                v-model="configuration.doc_type"
                outlined
                dense
                clearable
                data-cy="doc-type"
                :options="doc_type_list"
                emit-value
                map-options
                :placeholder="$t('select_document_type')"
              />
            </div>
          </div>

          <div class="export-form-row" :class="{ 'no-margin': !isInforSelected }">
            <div class="export-form-group" :class="isInforSelected ? '' : 'no-margin'">
              <label class="export-field-label">{{ $t('export_type') }} <span class="export-required">*</span></label>
              <!-- Selected Export Type Display (edit mode) -->
              <div v-if="selected_export && configuration.id && configuration.id !== 0" class="selected-export-display">
                <div class="export-badge">
                  <img v-if="getSelectedExportOption?.image" :src="getSelectedExportOption.image" class="export-badge-img" />
                  <q-icon v-else :name="getSelectedExportOption?.icon || 'upload'" size="16px" />
                </div>
                <div class="export-badge-info">
                  <span class="export-badge-label">{{ getSelectedExportOption?.label }}</span>
                  <span class="export-badge-hint">{{ $t('selected_integration') }}</span>
                </div>
              </div>
              <!-- Main Export Type Dropdown -->
              <q-select
                v-else
                v-model="mainExportSelection"
                outlined
                dense
                data-cy="export-type"
                :options="mainExportTypeOptions"
                option-value="value"
                option-label="label"
                emit-value
                map-options
                :placeholder="$t('select_export_type')"
              >
                <template v-slot:prepend v-if="mainExportSelection">
                  <img v-if="getMainExportOption?.image" :src="getMainExportOption.image" class="dropdown-icon-img" />
                  <q-icon v-else :name="getMainExportOption?.icon || 'upload'" size="18px" color="primary" />
                </template>
                <template v-slot:option="scope">
                  <q-item v-bind="scope.itemProps">
                    <q-item-section avatar class="dropdown-option-avatar">
                      <img v-if="scope.opt.image" :src="scope.opt.image" class="dropdown-icon-img" />
                      <q-icon v-else :name="scope.opt.icon" size="18px" color="primary" />
                    </q-item-section>
                    <q-item-section>
                      <q-item-label>{{ scope.opt.label }}</q-item-label>
                    </q-item-section>
                  </q-item>
                </template>
              </q-select>
            </div>

            <!-- Infor Sub-Type Dropdown (only shown when Infor is selected) -->
            <div v-if="isInforSelected && !(configuration.id && configuration.id !== 0)" class="export-form-group no-margin">
              <label class="export-field-label">{{ $t('infor_type') }} <span class="export-required">*</span></label>
              <q-select
                v-model="selectedInforSubType"
                outlined
                dense
                data-cy="infor-sub-type"
                :options="inforSubTypeOptions"
                option-value="value"
                option-label="label"
                emit-value
                map-options
                :placeholder="$t('select_infor_type')"
              >
                <template v-slot:prepend v-if="selectedInforSubType">
                  <img v-if="getSelectedInforOption?.image" :src="getSelectedInforOption.image" class="dropdown-icon-img" />
                  <q-icon v-else :name="getSelectedInforOption?.icon || 'upload'" size="18px" color="primary" />
                </template>
                <template v-slot:option="scope">
                  <q-item v-bind="scope.itemProps">
                    <q-item-section avatar class="dropdown-option-avatar">
                      <img v-if="scope.opt.image" :src="scope.opt.image" class="dropdown-icon-img" />
                      <q-icon v-else :name="scope.opt.icon" size="18px" color="primary" />
                    </q-item-section>
                    <q-item-section>
                      <q-item-label>{{ scope.opt.label }}</q-item-label>
                    </q-item-section>
                  </q-item>
                </template>
              </q-select>
            </div>
          </div>
        </div>

        <!-- Export Configuration -->
        <div class="card back-white" v-if="selected_export && selected_export !== 'infor'">
          <div class="card-title">{{ $t('export_configuration') }}</div>

          <!-- Webhook -->
          <template v-if="selected_export === export_types.WEBHOOK">
            <WebhookUrlField />
          </template>

          <!-- SFTP / SMB -->
          <template v-else-if="isSFTPorSMB">
            <SFTPSMBFields />
          </template>

          <!-- Infor SFTP -->
          <template v-else-if="selected_export === export_types.INFORSFTP">
            <InforSFTPExportFields>
              <template #mapping-files>
                <div class="files-grid">
                  <BodMappingFileField />
                  <IdmMappingFileField />
                </div>
              </template>
            </InforSFTPExportFields>
          </template>

          <!-- Infor IDM -->
          <template v-else-if="isInforIdmType">
            <DeploymentTypeField />
            <div class="files-grid">
              <IonApiFileField />
              <IdmMappingFileField />
            </div>
          </template>

          <!-- Infor ION BOD -->
          <template v-else-if="isInforBodType">
            <DeploymentTypeField />
            <div class="files-grid">
              <IonApiFileField />
              <BodMappingFileField />
            </div>
          </template>

          <!-- Infor ION (IDM + BOD) -->
          <template v-else-if="isInforIonType">
            <DeploymentTypeField />
            <div class="files-grid">
              <IonApiFileField />
              <IdmMappingFileField />
              <BodMappingFileField />
            </div>
          </template>

          <!-- Infor LN -->
          <template v-else-if="selected_export === export_types.INFOR_LN_CLOUD">
            <div class="files-grid">
              <IonApiFileField />
              <IdmMappingFileField />
              <LnMappingFileField />
            </div>
          </template>

          <!-- Infor M3 Cloud -->
          <template v-else-if="selected_export === export_types.INFOR_M3_CLOUD">
            <div class="files-grid">
              <IonApiFileField />
              <IdmMappingFileField />
              <M3MappingFileField />
            </div>
            <AutoValidateApproveFields />
          </template>

          <!-- Infor M3 TOML Cloud -->
          <template v-else-if="selected_export === export_types.INFOR_M3_TOML_CLOUD">
            <div class="files-grid">
              <IonApiFileField />
              <IdmMappingFileField />
              <TomlMappingFileField />
            </div>
            <AutoValidateApproveFields />
          </template>

          <!-- Infor GLS840MI / OC Charges / Packing Unit -->
          <template v-else-if="selected_export === export_types.INFOR_M3_OC_CHARGES_ONPREMISE || selected_export === export_types.INFOR_GLS840MI || selected_export === export_types.INFOR_M3_PACKING_UNIT_ONPREMISE">
            <div class="files-grid">
              <IonApiFileField />
              <TomlMappingFileField />
            </div>
            <AutoValidateApproveFields v-if="selected_export === export_types.INFOR_M3_OC_CHARGES_ONPREMISE" />
          </template>

          <!-- Generic API -->
          <template v-else-if="isGenericApiType">
            <DeploymentTypeField />
            <div class="files-grid">
              <ApiCredentialsMappingFileField />
              <TomlMappingFileField />
            </div>
          </template>

          <!-- Vertex -->
          <template v-else-if="selected_export === export_types.VERTEX">
            <div class="files-grid">
              <TomlMappingFileField />
            </div>
          </template>

          <!-- Watchdog XSLT -->
          <template v-else-if="selected_export === export_types.WATCHER">
            <WatcherFields ref="watcherFieldsRef" />
          </template>

          <!-- Info Banner -->
          <div class="hint-banner">
            <q-icon name="info_outline" size="16px" />
            <span>{{ getInfoBannerText }}</span>
          </div>
        </div>
      </div>

      <!-- Right Column - Execution Order (only when multiple export is enabled for selected doc type) -->
      <div v-if="isMultipleExportEnabled" class="side-column scrollable-column">
        <ExecutionOrderCard />
      </div>
    </div>

    <!-- Footer Actions -->
    <div class="page-footer back-white">
      <f-btn data-cy="back" appearance="cancel" :label="$t('cancel')" @click="goBack" />
      <f-btn
        :label="$t('save')"
        data-cy="save"
        icon="check"
        :disable="!canSave"
        :loading="processing"
        @click="saveConfig"
      />
    </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { isInvoice, CONSTANTS } from 'src/constants';
import { filterApiDocTypes } from 'src/utils/docTypeFilter';
import type { dynamicObj } from 'src/pages/assets';
import { exportApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import encryptionUtil from 'src/utils/encryptionUtil';
import { useDropdownStore, useDocExportStore, useDocAttributesStore } from 'src/store/main';
// Field components
import SubOrgSelect from './Fields/sub-org-select.vue';
import SFTPSMBFields from './Fields/SFTPSMBFields.vue';
import WatcherFields from './Fields/WatcherFields.vue';
import WebhookUrlField from './Fields/WebhookUrlField.vue';
import IonApiFileField from './Fields/IonApiFileField.vue';
import LnMappingFileField from './Fields/LnMappingFileField.vue';
import M3MappingFileField from './Fields/M3MappingFileField.vue';
import ExecutionOrderCard from './Fields/ExecutionOrderCard.vue';
import IdmMappingFileField from './Fields/IdmMappingFileField.vue';
import BodMappingFileField from './Fields/BodMappingFileField.vue';
import DeploymentTypeField from './Fields/DeploymentTypeField.vue';
import TomlMappingFileField from './Fields/TomlMappingFileField.vue';
import InforSFTPExportFields from './Fields/InforSFTPExportFields.vue';
import AutoValidateApproveFields from './Fields/AutoValidateApproveFields.vue';
import ApiCredentialsMappingFileField from './Fields/ApiCredentialsMappingFileField.vue';

export default defineComponent({
  name: 'manage-configuration',
  mixins: [helperMixin, encryptionUtil],
  components: {
    SubOrgSelect,
    WebhookUrlField,
    SFTPSMBFields,
    InforSFTPExportFields,
    DeploymentTypeField,
    IonApiFileField,
    IdmMappingFileField,
    BodMappingFileField,
    LnMappingFileField,
    M3MappingFileField,
    TomlMappingFileField,
    AutoValidateApproveFields,
    ExecutionOrderCard,
    WatcherFields,
    ApiCredentialsMappingFileField,
  },
  data() {
    const doc_export_store = useDocExportStore();
    const dropdown_store = useDropdownStore();
    const doc_attribute_store = useDocAttributesStore();

    return {
      doc_export_store,
      dropdown_store,
      doc_attribute_store,
      dataLoading: false,
    };
  },
  async mounted() {
    // Load dropdown data on mount (needed when page is refreshed directly)
    await this.loadRequiredData();
  },
  computed: {
    doc_type_list(): any {
      return filterApiDocTypes(this.dropdown_store.doc_type_list);
    },
    export_types(): any {
      return this.doc_export_store.export_types;
    },
    selected_export: {
      get(): any {
        return this.doc_export_store.selected_export;
      },
      set(val: any) {
        this.doc_export_store.selected_export = val;
      },
    },
    configuration(): any {
      return this.doc_export_store.selected_configuration;
    },
    processing: {
      get(): boolean {
        return this.doc_export_store.processing;
      },
      set(val: boolean) {
        this.doc_export_store.processing = val;
      },
    },
    config_saved: {
      get(): boolean {
        return this.doc_export_store.config_saved;
      },
      set(val: boolean) {
        this.doc_export_store.config_saved = val;
      },
    },
    onPremiseTypes(): string[] {
      return [
        this.export_types.INFOR_IDM_ON_PREMISE,
        this.export_types.INFOR_BOD_ON_PREMISE,
        this.export_types.INFOR_ION_ON_PREMISE,
      ];
    },
    // Main dropdown options (non-Infor types + "Infor" group item)
    mainExportTypeOptions(): Array<{ value: string; label: string; icon?: string; image?: string }> {
      return [
        { value: this.export_types.WEBHOOK, label: this.$t('export_type_webhook'), icon: 'upload' },
        { value: this.export_types.SFTP, label: this.$t('export_type_sftp'), icon: 'upload' },
        { value: this.export_types.INFORSFTP, label: this.$t('export_type_infor_sftp'), icon: 'upload' },
        { value: this.export_types.SMB_WITH_JPL, label: this.$t('export_type_smb'), icon: 'upload' },
        { value: this.export_types.GENERIC_API, label: this.$t('export_type_generic_api'), icon: 'upload' },
        { value: this.export_types.VERTEX, label: this.$t('export_type_vertex'), icon: 'upload' },
        { value: this.export_types.WATCHER, label: this.$t('watchdog'), icon: 'computer' },
        { value: 'infor', label: this.$t('infor'), image: '/images/infor.jpg' },
      ];
    },
    // Infor sub-type dropdown options
    allInforSubTypeOptions(): Array<{ value: string; label: string; icon?: string; image?: string }> {
      return [
        { value: this.export_types.INFOR_IDM_CLOUD, label: this.$t('export_type_infor_idm'), image: '/images/infor.jpg' },
        { value: this.export_types.INFOR_IDM_ON_PREMISE, label: this.$t('export_type_infor_idm'), image: '/images/infor.jpg' },
        { value: this.export_types.INFOR_BOD_CLOUD, label: this.$t('export_type_infor_bod'), image: '/images/infor.jpg' },
        { value: this.export_types.INFOR_BOD_ON_PREMISE, label: this.$t('export_type_infor_bod'), image: '/images/infor.jpg' },
        { value: this.export_types.INFOR_ION_CLOUD, label: this.$t('export_type_infor_ion'), image: '/images/infor.jpg' },
        { value: this.export_types.INFOR_ION_ON_PREMISE, label: this.$t('export_type_infor_ion'), image: '/images/infor.jpg' },
        { value: this.export_types.INFOR_LN_CLOUD, label: this.$t('export_type_infor_ln'), image: '/images/infor.jpg' },
        { value: this.export_types.INFOR_M3_CLOUD, label: this.$t('export_type_infor_m3'), image: '/images/infor.jpg' },
        { value: this.export_types.INFOR_M3_TOML_CLOUD, label: this.$t('export_type_infor_m3_toml'), image: '/images/infor.jpg' },
        { value: this.export_types.INFOR_M3_OC_CHARGES_ONPREMISE, label: this.$t('export_type_infor_m3_oc_charges'), image: '/images/infor.jpg' },
        { value: this.export_types.INFOR_GLS840MI, label: this.$t('export_type_infor_gls840mi'), image: '/images/infor.jpg' },
        { value: this.export_types.INFOR_M3_PACKING_UNIT_ONPREMISE, label: this.$t('export_type_infor_m3_packing_unit'), image: '/images/infor.jpg' },
      ];
    },
    inforSubTypeOptions(): Array<{ value: string; label: string; icon?: string; image?: string }> {
      const isEditMode = this.configuration?.id && this.configuration.id !== 0;
      if (isEditMode) {
        return this.allInforSubTypeOptions;
      }
      // For new configurations, filter out on-premise variants
      return this.allInforSubTypeOptions.filter(opt => !this.onPremiseTypes.includes(opt.value));
    },
    isInforSelected(): boolean {
      return this.selected_export === 'infor' || this.allInforSubTypeOptions.some(opt => opt.value === this.selected_export);
    },
    mainExportSelection: {
      get(): string {
        return this.isInforSelected ? 'infor' : this.selected_export;
      },
      set(val: string) {
        if (val === 'infor') {
          const preserved = {
            title: this.configuration?.title || '',
            doc_type: this.configuration?.doc_type || '',
            sub_org_id: this.configuration?.sub_org_id || null,
          };
          this.doc_export_store.selected_export = 'infor';
          this.doc_export_store.selected_configuration = { ...preserved };
        } else {
          this.onExportTypeChange(val);
        }
      },
    },
    selectedInforSubType: {
      get(): string | null {
        return this.isInforSelected && this.selected_export !== 'infor' ? this.selected_export : null;
      },
      set(val: string) {
        this.onExportTypeChange(val);
      },
    },
    getMainExportOption(): any {
      return this.mainExportTypeOptions.find(opt => opt.value === this.mainExportSelection);
    },
    getSelectedInforOption(): any {
      return this.allInforSubTypeOptions.find(opt => opt.value === this.selectedInforSubType);
    },
    isSFTPorSMB(): boolean {
      return [
        this.export_types.SFTP,
        this.export_types.SMB_WITH_JPL,
      ].includes(this.selected_export);
    },
    isGenericApiType(): boolean {
      return this.selected_export === this.export_types.GENERIC_API;
    },
    isInforIdmType(): boolean {
      return [
        this.export_types.INFOR_IDM_CLOUD,
        this.export_types.INFOR_IDM_ON_PREMISE,
      ].includes(this.selected_export);
    },
    isInforIonType(): boolean {
      return [
        this.export_types.INFOR_ION_CLOUD,
        this.export_types.INFOR_ION_ON_PREMISE,
      ].includes(this.selected_export);
    },
    isInforBodType(): boolean {
      return [
        this.export_types.INFOR_BOD_CLOUD,
        this.export_types.INFOR_BOD_ON_PREMISE,
      ].includes(this.selected_export);
    },
    // Watcher uses 'name' instead of 'title', this computed handles both
    configurationTitle: {
      get(): string {
        if (this.selected_export === this.export_types.WATCHER) {
          return this.configuration?.name || '';
        }
        return this.configuration?.title || '';
      },
      set(val: string) {
        if (this.selected_export === this.export_types.WATCHER) {
          this.configuration.name = val;
        } else {
          this.configuration.title = val;
        }
      },
    },
    canSave(): boolean {
      // Watcher uses 'name', others use 'title'
      const hasTitle = this.selected_export === this.export_types.WATCHER
        ? this.configuration?.name
        : this.configuration?.title;
      return !!(
        hasTitle &&
        this.selected_export &&
        Object.values(this.export_types).includes(this.selected_export) &&
        this.configuration?.doc_type
      );
    },
    getInfoBannerText(): string {
      const type = this.selected_export;
      if (type === this.export_types.WEBHOOK) {
        return this.$t('export_info_webhook');
      }
      if (type === this.export_types.SFTP) {
        return this.$t('export_info_sftp');
      }
      if (type === this.export_types.SMB_WITH_JPL) {
        return this.$t('export_info_smb');
      }
      if (type === this.export_types.INFORSFTP) {
        return this.$t('export_info_infor_sftp');
      }
      if ([this.export_types.INFOR_IDM_CLOUD, this.export_types.INFOR_IDM_ON_PREMISE].includes(type)) {
        return this.$t('export_info_infor_idm');
      }
      if ([this.export_types.INFOR_BOD_CLOUD, this.export_types.INFOR_BOD_ON_PREMISE].includes(type)) {
        return this.$t('export_info_infor_bod');
      }
      if ([this.export_types.INFOR_ION_CLOUD, this.export_types.INFOR_ION_ON_PREMISE].includes(type)) {
        return this.$t('export_info_infor_ion');
      }
      if (type === this.export_types.INFOR_LN_CLOUD) {
        return this.$t('export_info_infor_ln');
      }
      if ([this.export_types.INFOR_M3_CLOUD, this.export_types.INFOR_M3_TOML_CLOUD, this.export_types.INFOR_M3_OC_CHARGES_ONPREMISE].includes(type)) {
        return this.$t('export_info_infor_m3');
      }
      if (type === this.export_types.INFOR_GLS840MI) {
        return this.$t('export_info_infor_gls840mi');
      }
      if (type === this.export_types.INFOR_M3_PACKING_UNIT_ONPREMISE) {
        return this.$t('export_info_infor_m3_packing_unit');
      }
      if (type === this.export_types.VERTEX) {
        return this.$t('export_info_vertex');
      }
      if (type === this.export_types.GENERIC_API) {
        return this.$t('export_info_generic_api');
      }
      if (type === this.export_types.WATCHER) {
        return this.$t('export_info_watcher');
      }
      return this.$t('export_info_default');
    },
    getSelectedExportOption(): { value: string; label: string; icon?: string; image?: string } | undefined {
      return this.mainExportTypeOptions.find(opt => opt.value === this.selected_export)
        || this.allInforSubTypeOptions.find(opt => opt.value === this.selected_export);
    },
    getExportTypeLabel(): string {
      return this.getSelectedExportOption?.label || '';
    },
    isMultipleExportEnabled(): boolean {
      const docType = this.configuration?.doc_type;
      if (!docType) return false;
      return this.doc_attribute_store.getSettingsByDocTypeAndSettingKey(
        docType,
        CONSTANTS.ALLOW_MULTIPLE_EXPORT_CONFIGURATIONS,
      ) === true;
    },
  },
  methods: {
    isInvoice,
    async loadRequiredData() {
      try {
        this.dataLoading = true;

        // Load sub-organizations list
        await this.dropdown_store.getSubOrgsList();

        // Load document type list
        this.dropdown_store.fillDocTypeAndSubTypesListIfEmpty();

        // Load export configurations (needed for ExecutionOrderCard)
        await this.doc_export_store.getExportConfigurations();

        // Load doc type settings (needed for ALLOW_MULTIPLE_EXPORT_CONFIGURATIONS check)
        this.doc_attribute_store.getDocTypeAllSettings();

        // Handle edit mode: restore configuration from URL param if needed
        const routeId = this.$route.params.id as string;
        if (routeId && routeId !== 'new') {
          // Check if configuration is already loaded in store
          if (!this.configuration.id || this.configuration.id === 0) {
            // Configuration was lost (page refresh), try to restore from configurations list
            const configs = this.doc_export_store.configurations || [];
            const existingConfig = configs.find((c: any) => String(c.id) === routeId);
            if (existingConfig) {
              this.doc_export_store.setSelectedExportForEdit(JSON.parse(JSON.stringify(existingConfig)));
            }
          }
        }
      } catch (err: any) {
        logError(err);
      } finally {
        this.dataLoading = false;
      }
    },
    goBack() {
      this.doc_export_store.clearStateForExportDialog();
      this.$router.push('/settings/export');
    },
    onExportTypeChange(val: string) {
      // Allow configuring all export types including Watchdog directly on this page
      this.doc_export_store.selectedNewExport(val);
    },

    // ===== VALIDATION METHODS =====

    // Validate common fields required for all export types
    validateCommonFields(): string[] {
      const errors: string[] = [];
      if (!this.configuration.title?.trim()) {
        errors.push(this.$t('config_title_required'));
      }
      if (!this.configuration.doc_type) {
        errors.push(this.$t('doc_type_required'));
      }
      if (!this.selected_export) {
        errors.push(this.$t('export_type_required'));
      }
      return errors;
    },

    // Validate Webhook configuration
    validateWebhook(): string[] {
      const errors = this.validateCommonFields();
      if (!this.configuration.export_url?.trim()) {
        errors.push(this.$t('webhook_url_required'));
      }
      return errors;
    },

    // Validate SFTP configuration
    validateSFTP(): string[] {
      const errors = this.validateCommonFields();
      const isNewConfig = !this.configuration.id || this.configuration.id === 0;

      if (!this.configuration.export_url?.trim()) {
        errors.push(this.$t('server_url_required'));
      }
      if (!this.configuration.export_port) {
        errors.push(this.$t('port_required'));
      }
      if (!this.configuration.username?.trim()) {
        errors.push(this.$t('username_required'));
      }
      // Password is required only for new configurations (existing configs have it saved on server)
      if (isNewConfig && !this.configuration.password?.trim()) {
        errors.push(this.$t('password_required'));
      }
      if (!this.configuration.export_folder?.trim()) {
        errors.push(this.$t('export_folder_required'));
      }
      return errors;
    },

    // Validate SMB configuration (same as SFTP)
    validateSMB(): string[] {
      return this.validateSFTP();
    },

    // Validate Infor SFTP configuration
    validateInforSFTP(): string[] {
      const errors = this.validateCommonFields();
      if (!this.configuration.export_folder?.trim()) {
        errors.push(this.$t('export_folder_required'));
      }
      return errors;
    },

    // Validate Infor IDM configuration
    validateIdm(): string[] {
      const errors = this.validateCommonFields();
      if (!this.configuration.ion_file && !this.configuration.infor_ion_api) {
        errors.push(this.$t('ion_api_file_required'));
      }
      if (!this.configuration.idm_file && !this.configuration.infor_idm_mapping) {
        errors.push(this.$t('idm_mapping_file_required'));
      }
      return errors;
    },

    // Validate Infor BOD configuration
    validateBod(): string[] {
      const errors = this.validateCommonFields();
      if (!this.configuration.ion_file && !this.configuration.infor_ion_api) {
        errors.push(this.$t('ion_api_file_required'));
      }
      if (!this.configuration.bod_file && !this.configuration.infor_bod_mapping) {
        errors.push(this.$t('bod_mapping_file_required'));
      }
      return errors;
    },

    // Validate Infor ION (IDM + BOD) configuration
    validateIon(): string[] {
      const errors = this.validateCommonFields();
      if (!this.configuration.ion_file && !this.configuration.infor_ion_api) {
        errors.push(this.$t('ion_api_file_required'));
      }
      if (!this.configuration.idm_file && !this.configuration.infor_idm_mapping) {
        errors.push(this.$t('idm_mapping_file_required'));
      }
      if (!this.configuration.bod_file && !this.configuration.infor_bod_mapping) {
        errors.push(this.$t('bod_mapping_file_required'));
      }
      return errors;
    },

    // Validate Infor LN configuration
    validateLN(): string[] {
      const errors = this.validateCommonFields();
      if (!this.configuration.ion_file && !this.configuration.infor_ion_api) {
        errors.push(this.$t('ion_api_file_required'));
      }
      if (!this.configuration.idm_file && !this.configuration.infor_idm_mapping) {
        errors.push(this.$t('idm_mapping_file_required'));
      }
      if (!this.configuration.ln_file && !this.configuration.infor_ln_mapping) {
        errors.push(this.$t('ln_mapping_file_required'));
      }
      return errors;
    },

    // Validate Infor M3 configuration
    validateM3(): string[] {
      const errors = this.validateCommonFields();
      const exportType = this.selected_export;

      if (!this.configuration.ion_file && !this.configuration.infor_ion_api) {
        errors.push(this.$t('ion_api_file_required'));
      }

      // M3 Cloud and M3 TOML Cloud require IDM mapping
      if (exportType === this.export_types.INFOR_M3_CLOUD || exportType === this.export_types.INFOR_M3_TOML_CLOUD) {
        if (!this.configuration.idm_file && !this.configuration.infor_idm_mapping) {
          errors.push(this.$t('idm_mapping_file_required'));
        }
      }

      // M3 Cloud requires M3 mapping
      if (exportType === this.export_types.INFOR_M3_CLOUD) {
        if (!this.configuration.m3_file && !this.configuration.infor_m3_mapping) {
          errors.push(this.$t('m3_mapping_file_required'));
        }
      }

      // M3 TOML Cloud requires TOML mapping
      if (exportType === this.export_types.INFOR_M3_TOML_CLOUD) {
        if (!this.configuration.toml_file && !this.configuration.infor_m3_toml_mapping && !this.configuration.m3_toml_mapping_id) {
          errors.push(this.$t('toml_mapping_file_required'));
        }
      }

      return errors;
    },

    // Validate ION API + TOML mapping configuration (used by GLS840MI and OC Charges)
    validateIonApiToml(): string[] {
      const errors = this.validateCommonFields();
      if (!this.configuration.ion_file && !this.configuration.infor_ion_api && !this.configuration.infor_ion_api_id) {
        errors.push(this.$t('ion_api_file_required'));
      }
      if (!this.configuration.toml_file && !this.configuration.infor_m3_toml_mapping && !this.configuration.m3_toml_mapping_id) {
        errors.push(this.$t('toml_mapping_file_required'));
      }
      return errors;
    },

    // Validate Vertex configuration (TOML mapping only)
    validateVertex(): string[] {
      const errors = this.validateCommonFields();
      if (!this.configuration.toml_file && !this.configuration.infor_m3_toml_mapping && !this.configuration.m3_toml_mapping_id) {
        errors.push(this.$t('toml_mapping_file_required'));
      }
      return errors;
    },

    // Validate Generic API configuration (TOML mapping + credentials file)
    validateGenericApi(): string[] {
      const errors = this.validateCommonFields();
      if (!this.configuration.toml_file && !this.configuration.infor_m3_toml_mapping && !this.configuration.m3_toml_mapping_id) {
        errors.push(this.$t('toml_mapping_file_required'));
      }
      if (!this.configuration.credentials_file && !this.configuration.api_credentials_mapping && !this.configuration.api_credentials_mapping_id) {
        errors.push(this.$t('api_credentials_file_required'));
      }
      return errors;
    },

    // Validate Watcher configuration
    validateWatcher(): string[] {
      const errors: string[] = [];
      // Watcher uses 'name' instead of 'title'
      if (!this.configuration.name?.trim()) {
        errors.push(this.$t('config_title_required'));
      }
      if (!this.configuration.doc_type) {
        errors.push(this.$t('doc_type_required'));
      }
      if (!this.configuration.export_folder?.trim()) {
        errors.push(this.$t('export_folder_required'));
      }
      return errors;
    },

    // Get validation errors based on export type
    getValidationErrors(): string[] {
      const exportType = this.selected_export;

      if (exportType === this.export_types.WEBHOOK) {
        return this.validateWebhook();
      } else if (exportType === this.export_types.SFTP) {
        return this.validateSFTP();
      } else if (exportType === this.export_types.SMB_WITH_JPL) {
        return this.validateSMB();
      } else if (exportType === this.export_types.INFORSFTP) {
        return this.validateInforSFTP();
      } else if ([this.export_types.INFOR_IDM_CLOUD, this.export_types.INFOR_IDM_ON_PREMISE].includes(exportType)) {
        return this.validateIdm();
      } else if ([this.export_types.INFOR_BOD_CLOUD, this.export_types.INFOR_BOD_ON_PREMISE].includes(exportType)) {
        return this.validateBod();
      } else if ([this.export_types.INFOR_ION_CLOUD, this.export_types.INFOR_ION_ON_PREMISE].includes(exportType)) {
        return this.validateIon();
      } else if (exportType === this.export_types.INFOR_LN_CLOUD) {
        return this.validateLN();
      } else if ([this.export_types.INFOR_M3_CLOUD, this.export_types.INFOR_M3_TOML_CLOUD].includes(exportType)) {
        return this.validateM3();
      } else if (exportType === this.export_types.INFOR_M3_OC_CHARGES_ONPREMISE || exportType === this.export_types.INFOR_GLS840MI || exportType === this.export_types.INFOR_M3_PACKING_UNIT_ONPREMISE) {
        return this.validateIonApiToml();
      } else if (exportType === this.export_types.VERTEX) {
        return this.validateVertex();
      } else if (this.isGenericApiType) {
        return this.validateGenericApi();
      } else if (exportType === this.export_types.WATCHER) {
        return this.validateWatcher();
      }

      return this.validateCommonFields();
    },

    // Show validation errors to user
    showValidationErrors(errors: string[]) {
      const errorList = errors.map(e => `• ${e}`).join('\n');
      notify.error(`${this.$t('please_fix_errors_before_saving')}:\n${errorList}`);
    },

    // ===== END VALIDATION METHODS =====

    async saveConfig() {
      // Validate before saving
      const errors = this.getValidationErrors();
      if (errors.length > 0) {
        this.showValidationErrors(errors);
        return;
      }

      try {
        this.processing = true;
        const exportType = this.selected_export;

        // Build config based on export type
        if (exportType === this.export_types.WEBHOOK) {
          await this.saveWebhookConfig();
        } else if (exportType === this.export_types.SFTP) {
          await this.saveSFTPConfig();
        } else if (exportType === this.export_types.SMB_WITH_JPL) {
          await this.saveSMBConfig();
        } else if (exportType === this.export_types.INFORSFTP) {
          await this.saveInforSFTPConfig();
        } else if ([this.export_types.INFOR_IDM_CLOUD, this.export_types.INFOR_IDM_ON_PREMISE].includes(exportType)) {
          await this.saveIdmConfig();
        } else if ([this.export_types.INFOR_BOD_CLOUD, this.export_types.INFOR_BOD_ON_PREMISE].includes(exportType)) {
          await this.saveBodConfig();
        } else if ([this.export_types.INFOR_ION_CLOUD, this.export_types.INFOR_ION_ON_PREMISE].includes(exportType)) {
          await this.saveIonConfig();
        } else if (exportType === this.export_types.INFOR_LN_CLOUD) {
          await this.saveLNConfig();
        } else if ([this.export_types.INFOR_M3_CLOUD, this.export_types.INFOR_M3_TOML_CLOUD].includes(exportType)) {
          await this.saveM3Config();
        } else if (exportType === this.export_types.INFOR_M3_OC_CHARGES_ONPREMISE || exportType === this.export_types.INFOR_GLS840MI || exportType === this.export_types.INFOR_M3_PACKING_UNIT_ONPREMISE) {
          await this.saveIonApiTomlConfig();
        } else if (exportType === this.export_types.VERTEX) {
          await this.saveVertexConfig();
        } else if (this.isGenericApiType) {
          await this.saveGenericApiConfig();
        } else if (exportType === this.export_types.WATCHER) {
          await this.saveWatcherConfig();
        }

        notify.success(this.$t('MSG_SAVE'));
        this.config_saved = true;
        this.goBack();
      } catch (err: any) {
        logError(err);
        // Prefer the API message (includes dynamic details like doc type) over generic i18n translation
        const apiMessage = err?.response?.data?.message || err?.data?.message || err?.message;
        if (apiMessage) {
          notify.error(apiMessage);
        } else {
          const detail_info = err.extra_data ? err.extra_data : '';
          const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
          notify.error(msg + ' ' + detail_info);
        }
      } finally {
        this.processing = false;
      }
    },

    // Helper: Build base config with common fields
    buildBaseConfig(exportMethod: string): any {
      const config: any = {
        export_method: exportMethod,
        doc_type: this.configuration.doc_type,
        title: this.configuration.title,
      };
      this.addCommonFields(config);
      return config;
    },

    // Helper: Add file mapping if exists
    addFileMapping(config: any, formField: string, apiField: string, checkType = false) {
      const value = this.configuration[formField];
      if (value && (!checkType || typeof value !== 'string')) {
        config[apiField] = value;
      }
    },

    // Helper: Add advanced attributes for SFTP-type exports
    addAdvancedAttributes(config: any) {
      config.additional_attributes = JSON.stringify({
        export_with_docbits_id_as_filename: this.configuration.filename_export_mode || false,
        include_document_history: this.configuration.export_document_history || false,
      });
    },

    // Helper: Get cloud-aware export method
    getCloudExportMethod(cloudType: string, onPremType: string): string {
      return this.configuration.cloud ? cloudType : onPremType;
    },

    async saveWebhookConfig() {
      const config = this.buildBaseConfig(this.export_types.WEBHOOK);
      config.export_url = this.configuration.export_url;
      const response = await exportApiService.saveWebhookConfig(config);
      this.handleResponse(response);
    },

    async saveSFTPConfig() {
      const config = this.buildBaseConfig(this.export_types.SFTP);
      Object.assign(config, {
        server_url: this.configuration.export_url,
        port: this.configuration.export_port,
        export_folder: this.configuration.export_folder,
        username: this.configuration.username,
      });
      // Only send password if it's provided (to avoid overwriting existing password)
      if (this.configuration.password?.trim()) {
        config.password = this.encryptPassword(this.configuration.password);
      }
      this.addAdvancedAttributes(config);
      this.addFileMapping(config, 'export_xslt_file', 'export_xslt');
      const response = await exportApiService.saveSFTPConfig(config);
      this.handleResponse(response);
    },

    async saveSMBConfig() {
      const config = this.buildBaseConfig(this.export_types.SMB_WITH_JPL);
      Object.assign(config, {
        server_url: this.configuration.export_url,
        port: this.configuration.export_port,
        export_folder: this.configuration.export_folder,
        username: this.configuration.username,
      });
      // Only send password if it's provided (to avoid overwriting existing password)
      if (this.configuration.password?.trim()) {
        config.password = this.encryptPassword(this.configuration.password);
      }
      this.addFileMapping(config, 'jpl_mapping_file', 'jpl_mapping');
      const response = await exportApiService.saveSMBConfig(config);
      this.handleResponse(response);
    },

    async saveInforSFTPConfig() {
      const config = this.buildBaseConfig(this.export_types.INFORSFTP);
      config.export_folder = this.configuration.export_folder;
      this.addFileMapping(config, 'bod_file', 'bod_mapping', true);
      this.addFileMapping(config, 'idm_file', 'idm_mapping', true);
      this.addAdvancedAttributes(config);
      const response = await exportApiService.saveInforSFTPConfig(config);
      this.handleResponse(response);
    },

    async saveIdmConfig() {
      const exportMethod = this.getCloudExportMethod(this.export_types.INFOR_IDM_CLOUD, this.export_types.INFOR_IDM_ON_PREMISE);
      const config = this.buildBaseConfig(exportMethod);
      this.addFileMapping(config, 'ion_file', 'ion_api');
      this.addFileMapping(config, 'idm_file', 'idm_mapping');
      const response = await exportApiService.saveInforConfig(config);
      this.handleResponse(response);
    },

    async saveBodConfig() {
      const exportMethod = this.getCloudExportMethod(this.export_types.INFOR_BOD_CLOUD, this.export_types.INFOR_BOD_ON_PREMISE);
      const config = this.buildBaseConfig(exportMethod);
      this.addFileMapping(config, 'ion_file', 'ion_api');
      this.addFileMapping(config, 'bod_file', 'bod_mapping');
      const response = await exportApiService.saveInforConfig(config);
      this.handleResponse(response);
    },

    async saveIonConfig() {
      const exportMethod = this.getCloudExportMethod(this.export_types.INFOR_ION_CLOUD, this.export_types.INFOR_ION_ON_PREMISE);
      const config = this.buildBaseConfig(exportMethod);
      this.addFileMapping(config, 'ion_file', 'ion_api');
      this.addFileMapping(config, 'idm_file', 'idm_mapping');
      this.addFileMapping(config, 'bod_file', 'bod_mapping');
      const response = await exportApiService.saveInforConfig(config);
      this.handleResponse(response);
    },

    async saveLNConfig() {
      const config = this.buildBaseConfig(this.export_types.INFOR_LN_CLOUD);
      this.addFileMapping(config, 'ion_file', 'ion_api');
      this.addFileMapping(config, 'idm_file', 'idm_mapping');
      this.addFileMapping(config, 'ln_file', 'ln_mapping');
      const response = await exportApiService.saveInforConfig(config);
      this.handleResponse(response);
    },

    async saveM3Config() {
      const config = this.buildBaseConfig(this.selected_export);
      config.auto_approve_after_export = false;
      config.auto_validate_after_export = false;

      this.addFileMapping(config, 'ion_file', 'ion_api');
      this.addFileMapping(config, 'idm_file', 'idm_mapping');
      this.addFileMapping(config, 'm3_file', 'm3_mapping');
      this.addFileMapping(config, 'toml_file', 'm3_toml_mapping');

      if (this.configuration.m3_toml_mapping_id) {
        config.m3_toml_mapping_id = this.configuration.m3_toml_mapping_id;
      }

      if (this.isInvoice(this.configuration.doc_type)) {
        config.auto_approve_after_export = this.configuration.auto_approve_after_export;
        config.auto_validate_after_export = this.configuration.auto_validate_after_export;
      }

      const response = await exportApiService.saveInforConfig(config);
      this.handleResponse(response);
    },

    async saveIonApiTomlConfig() {
      const isOcCharges = this.selected_export === this.export_types.INFOR_M3_OC_CHARGES_ONPREMISE;
      const exportType = this.selected_export;
      const config = this.buildBaseConfig(exportType);

      this.addFileMapping(config, 'ion_file', 'ion_api');
      this.addFileMapping(config, 'toml_file', 'api_export_mapping');

      // Transform m3_toml_mapping_id → api_export_mapping_id for server
      if (this.configuration.m3_toml_mapping_id) {
        config.api_export_mapping_id = this.configuration.m3_toml_mapping_id;
      }

      // OC Charges supports auto-validate/approve
      if (isOcCharges) {
        config.auto_approve_after_export = false;
        config.auto_validate_after_export = false;
        if (this.isInvoice(this.configuration.doc_type)) {
          config.auto_approve_after_export = this.configuration.auto_approve_after_export;
          config.auto_validate_after_export = this.configuration.auto_validate_after_export;
        }
      }

      const response = await exportApiService.saveInforConfig(config);
      this.handleResponse(response);
    },

    async saveVertexConfig() {
      const config = this.buildBaseConfig(this.export_types.VERTEX);
      config.export_type = this.export_types.VERTEX;

      this.addFileMapping(config, 'toml_file', 'vertex_mapping');

      if (this.configuration.m3_toml_mapping_id) {
        config.vertex_mapping_id = this.configuration.m3_toml_mapping_id;
      }

      const response = await exportApiService.saveVertexConfig(config);
      this.handleResponse(response);
    },

    async saveGenericApiConfig() {
      const config = this.buildBaseConfig(this.export_types.GENERIC_API);
      config.export_type = 'generic_api';
      config.on_premise = !this.configuration.cloud;

      this.addFileMapping(config, 'toml_file', 'api_export_mapping');
      this.addFileMapping(config, 'credentials_file', 'api_credentials_mapping');

      if (this.configuration.m3_toml_mapping_id) {
        config.api_export_mapping_id = this.configuration.m3_toml_mapping_id;
      }
      if (this.configuration.api_credentials_mapping_id) {
        config.api_credentials_mapping_id = this.configuration.api_credentials_mapping_id;
      }

      const response = await exportApiService.saveGenericApiConfig(config);
      this.handleResponse(response);
    },

    async saveWatcherConfig() {
      // Check if this is a true Watchdog config (UUID ID, is_watchdog flag)
      // or a regular export config with export_method='watcher' (numeric ID)
      const isWatchdogConfig = this.configuration.is_watchdog === true;

      if (isWatchdogConfig) {
        // True Watchdog configuration - use Watchdog API
        await this.saveWatchdogConfig();
      } else {
        // Regular watcher export configuration - use export configurations API
        await this.saveRegularWatcherConfig();
      }
    },

    async saveWatchdogConfig() {
      const config: dynamicObj = {
        name: this.configuration.name,
        config_type: 'export',
        enabled: this.configuration.enabled,
        export_folder: this.configuration.export_folder,
        doc_type: this.configuration.doc_type,
        export_method: this.export_types.WATCHER,
      };

      // Handle XSLT template - check if new file was uploaded
      const watcherFieldsRef = this.$refs.watcherFieldsRef as any;
      if (watcherFieldsRef?.newTemplateFile) {
        const templateId = await watcherFieldsRef.uploadTemplateIfNeeded();
        if (templateId) {
          config.xslt_template_id = templateId;
        }
      } else if (this.configuration.xslt_template_id) {
        config.xslt_template_id = this.configuration.xslt_template_id;
      }

      if (this.configuration.sub_org_id != null) {
        config.sub_org_id = this.configuration.sub_org_id;
      }

      let response;
      if (this.configuration.id && this.configuration.id !== '') {
        // Update existing configuration
        response = await exportApiService.updateWatchdogConfiguration(
          this.configuration.id,
          config,
        );
      } else {
        // Create new configuration
        response = await exportApiService.saveWatchdogConfiguration(config);
      }

      // CRITICAL FIX: Check response and throw error if save failed
      // Backend returns { success: boolean, configuration: object | null, message: string }
      if (!response.success || !response.configuration) {
        throw new Error(response.message || 'Failed to save configuration');
      }
    },

    async saveRegularWatcherConfig() {
      // Regular watcher export - uses export_configurations table
      const config: dynamicObj = {
        doc_type: this.configuration.doc_type,
        title: this.configuration.title || this.configuration.name,
        export_folder: this.configuration.export_folder,
        is_active: this.configuration.enabled ?? true,
        export_method: this.export_types.WATCHER,
      };

      // Add config_id for updates
      if (this.configuration.id && this.configuration.id !== 0) {
        config.config_id = this.configuration.id;
      }

      if (this.configuration.sub_org_id != null) {
        config.sub_org_id = this.configuration.sub_org_id;
      }

      if (this.configuration.execution_order) {
        config.execution_order = this.configuration.execution_order;
      }

      // Handle XSLT template
      const watcherFieldsRef = this.$refs.watcherFieldsRef as any;
      if (watcherFieldsRef?.newTemplateFile) {
        const templateId = await watcherFieldsRef.uploadTemplateIfNeeded();
        if (templateId) {
          config.xslt_template_id = templateId;
        }
      } else if (this.configuration.xslt_template_id) {
        config.xslt_template_id = this.configuration.xslt_template_id;
      }

      // Handle PDF export settings
      if (this.configuration.export_pdf_enabled) {
        config.export_pdf_enabled = this.configuration.export_pdf_enabled;
        if (this.configuration.pdf_export_folder) {
          config.pdf_export_folder = this.configuration.pdf_export_folder;
        }
      }

      const response = await exportApiService.saveWatcherExportConfig(config);
      this.handleResponse(response);
    },

    addCommonFields(config: any) {
      if (this.configuration.id !== 0) {
        config.config_id = this.configuration.id;
      }
      if (this.configuration.sub_org_id != null) {
        config.sub_org_id = this.configuration.sub_org_id;
      }
      if (this.configuration.execution_order) {
        config.execution_order = this.configuration.execution_order;
      }
    },

    handleResponse(response: any) {
      // CRITICAL FIX: Check for backend validation errors and throw if save failed
      // Backend may return errors in different formats:
      // - { success: false, message: "error" } - validation/business logic errors
      // - { success: false, exception: { detail: "error" } } - exception errors
      if (response && !response.success) {
        const errorMessage = response.exception?.detail
          || response.message
          || 'Failed to save configuration';
        throw { message: errorMessage };
      }
    },
  },
});
</script>

